  }

  const cleanBase64 = imageBase64.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  // Scaled Intensity values for Safety to ensure natural look (ID Photo Standard)
  const smoothSafe = Math.round((beautySettings.smoothSkin / 100) * 50); // Max 50% - Avoid plastic skin
  const blemishSafe = Math.round((beautySettings.blemishIntensity / 100) * 70); // Max 70% - Keep main features
  const lipstickSafe = Math.round((beautySettings.lipstickIntensity / 100) * 40); // Max 40% - Natural look
  const blushSafe = Math.round((beautySettings.blushIntensity / 100) * 30); // Max 30% - Subtle

  const contourSafe = Math.round((beautySettings.contourIntensity / 100) * 30); // Max 30% - No drastic shape change
  const eyebrowSafe = Math.round((beautySettings.eyebrowIntensity / 100) * 50); // Max 50%
  const eyelashSafe = Math.round((beautySettings.eyelashIntensity / 100) * 40); // Max 40%
  const hairVolSafe = Math.round((beautySettings.hairVolume / 100) * 50); // Max 50%

  const backgroundInstructions = bgType === BackgroundType.ORIGINAL 
